import logging, json, time

logger = logging.getLogger("app")

class JsonFormatter(logging.Formatter):
    def format(self, record):
        base = {"ts": self.formatTime(record), "level": record.levelname,
                "logger": record.name, "msg": record.getMessage()}
        base.update(getattr(record, "extra_fields", {}))
        return json.dumps(base, ensure_ascii=False)

def log_llm_call(trace_id, model, usage, cost, latency):
    logger.info("llm_call", extra={"extra_fields": {
        "trace_id": trace_id, "model": model,
        "in_toks": usage.input, "out_toks": usage.output,
        "cost_usd": round(cost, 5), "latency_ms": latency}})
